ROOT.scriptdef:
CREATE FUNCTION [CDN].[ProdProdukty] (@PzlId int,@Typ int) RETURNS TABLE AS
RETURN ( SELECT SUBSTRING(P.Produkt,1,LEN(P.Produkt)-1) Kod FROM (SELECT REPLACE(REPLACE((SELECT t.kod + ',' from (Select case when @Typ = 0 then Twr_Kod else Twr_Nazwa end Kod From CDN.ProdZlecenia inner join CDN.ProdCzynnosci on PCZ_PZLId = PZL_Id inner join CDN.Rezerwacje on PCZ_Id=Rez_ZrdNumer and Rez_ZrdTyp = 14345 inner join CDN.TwrKarty on Twr_GIDNumer = Rez_TwrNumer where PZL_Id=@PzlId and Rez_GIDTyp = 2592 union all select case when @Typ = 0 then isnull(T.Twr_Kod,PTZ_Kod) else ISNULL(T.Twr_Nazwa,PTZ_Nazwa) end Kod From CDN.ProdZlecenia inner join CDN.ProdCzynnosci on PZL_Id = PCZ_PZLId inner join CDN.ProdZasoby Z on Z.PZA_Czynnosc = PCZ_Id inner join CDN.TwrKarty T on T.Twr_GIDNumer = Z.PZA_TwrNumer left outer join CDN.ProdTechnologiaZasoby on PTZ_Id = Z.PZA_TechnologiaZasob --left outer join Cdn.ProdZasoby Sur on Sur.PZA_Zasob = Z.Pza_Id where PZL_Id= @PzlId and ISNULL(PTZ_TypZasobu,Z.PZA_TypZasobu) IN (0,4)) T ORDER BY T.Kod FOR XML PATH('')),'&lt;','<'),'&gt;','>') AS Produkt) P)
/*SELECT cdn.Concatenate(Kod+',') Kod from ( Select case when @Typ = 0 then Twr_Kod else Twr_Nazwa end Kod From CDN.ProdZlecenia inner join CDN.ProdCzynnosci on PCZ_PZLId = PZL_Id inner join CDN.Rezerwacje on PCZ_Id=Rez_ZrdNumer and Rez_ZrdTyp = 14345 inner join CDN.TwrKarty on Twr_GIDNumer = Rez_TwrNumer where PZL_Id=@PzlId and Rez_GIDTyp = 2592 union all select case when @Typ = 0 then isnull(T.Twr_Kod,PTZ_Kod) else ISNULL(T.Twr_Nazwa,PTZ_Nazwa) end Kod From CDN.ProdZlecenia inner join CDN.ProdCzynnosci on PZL_Id = PCZ_PZLId inner join CDN.ProdZasoby Z on Z.PZA_Czynnosc = PCZ_Id inner join CDN.TwrKarty T on T.Twr_GIDNumer = Z.PZA_TwrNumer left outer join CDN.ProdTechnologiaZasoby on PTZ_Id = Z.PZA_TechnologiaZasob --left outer join Cdn.ProdZasoby Sur on Sur.PZA_Zasob = Z.Pza_Id where PZL_Id= @PzlId and ISNULL(PTZ_TypZasobu,Z.PZA_TypZasobu) IN (0,4) ) T )*/
